import pyomo.environ as pyo

DATA = {
    "positions": ["X", "Y"],
    "max_total_hires": 50,
    "cost_X": 5000,
    "cost_Y": 8000,
    "ratio_X_to_notY": 3,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.P = pyo.Set(initialize=d["positions"])

    cost = {"X": d["cost_X"], "Y": d["cost_Y"]}

    model.hire = pyo.Var(
        model.P,
        within=pyo.NonNegativeIntegers,
        bounds=(0, d["max_total_hires"]),
    )

    def obj_rule(m):
        return sum(cost[p] * m.hire[p] for p in m.P)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def total_hires_rule(m):
        return sum(m.hire[p] for p in m.P) <= d["max_total_hires"]

    model.total_hires = pyo.Constraint(rule=total_hires_rule)

    def ratio_rule(m):
        not_hired_Y = d["max_total_hires"] - m.hire["Y"]
        return m.hire["X"] >= d["ratio_X_to_notY"] * not_hired_Y

    model.ratio = pyo.Constraint(rule=ratio_rule)

    return model
